const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get order details
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'W4669380'\").get();
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Get order items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'W4669380'\").all();
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Get fulfillments
const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'W4669380'\").all();
console.log('\n=== FULFILLMENTS ===');
console.log(JSON.stringify(fulfillments, null, 2));

