console.log('\n=== PAYMENTS ===');
console.log(JSON.stringify(payments, null, 2));

// Get customer info
if (order) {
  const user = db.prepare(\"SELECT user_id, name, email, loyalty_tier, loyalty_points, store_credit_balance, address_json FROM users WHERE user_id = ?\").get(order.customer_id);
