  }

  // Get payment methods
  const pmethods = db.prepare(\"SELECT * FROM rt_payment_methods WHERE user_id = ?\").all(order.customer_id);
  console.log('\n=== PAYMENT METHODS ===');
  console.log(JSON.stringify(pmethods, null, 2));
}
