node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const crypto = require('crypto');

// The return window is 30 days from delivery (Sep 5, 2026) = Oct 5, 2026
// Create a reminder a few days before the return window closes
const reminderId = crypto.randomUUID();
const now = new Date('2026-09-10T17:00:00Z');
const reminderDate = new Date('2026-10-03T09:00:00Z'); // Oct 3, 2 days before return window closes

const creationTimestamp = Math.floor(now.getTime() / 1000);
const reminderTimestamp = Math.floor(reminderDate.getTime() / 1000);

const content = 'Reminder: Your Everyday Crew Tee (Black, Size S) from order #W4669380 has a 30-day return window that expires on October 5, 2026. If you wish to return or exchange this item, please do so before the deadline.';

db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at)
  VALUES (?, ?, ?, ?, NULL, NULL, ?)
\`).run(reminderId, content, creationTimestamp, reminderTimestamp, now.toISOString().replace('Z',''));

console.log('Reminder created successfully!');
console.log('Reminder ID:', reminderId);
console.log('Content:', content);
console.log('Remind on:', reminderDate.toISOString());

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('\nVerification:', JSON.stringify(row, null, 2));
"
